@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_container">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _container;
    private IJSObjectReference? _module;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/UserActivityTracker.razor.js");
            await _module.InvokeVoidAsync("initialize", _container, _dotNetRef, TimeoutSeconds);
        }
    }

    [JSInvokable]
    public async Task OnIdleTriggered()
    {
        await OnIdle.InvokeAsync();
    }

    [JSInvokable]
    public async Task OnActiveTriggered()
    {
        await OnActive.InvokeAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            try
            {
                await _module.InvokeVoidAsync("dispose");
                await _module.DisposeAsync();
            }
            catch (JSDisconnectedException)
            {
                // Circuit may already be gone during server-side dispose
            }
        }
        _dotNetRef?.Dispose();
    }
}

let timerId = null;
let dotNetRef = null;
let isIdle = false;
let timeoutMs = 0;
let container = null;

const activityEvents = ["mousemove", "keydown", "click", "scroll"];

function onActivity() {
    if (isIdle) {
        isIdle = false;
        dotNetRef.invokeMethodAsync("OnActiveTriggered");
    }
    resetTimer();
}

function resetTimer() {
    if (timerId !== null) {
        clearTimeout(timerId);
    }
    timerId = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("OnIdleTriggered");
    }, timeoutMs);
}

export function initialize(element, ref, timeoutSeconds) {
    container = element;
    dotNetRef = ref;
    timeoutMs = timeoutSeconds * 1000;
    isIdle = false;

    for (const event of activityEvents) {
        container.addEventListener(event, onActivity, { passive: true });
    }

    resetTimer();
}

export function dispose() {
    if (timerId !== null) {
        clearTimeout(timerId);
        timerId = null;
    }

    if (container) {
        for (const event of activityEvents) {
            container.removeEventListener(event, onActivity);
        }
        container = null;
    }

    dotNetRef = null;
    isIdle = false;
}

